export function findById(id){return ACTIVITIES.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return ACTIVITIES.slice();return ACTIVITIES.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return ACTIVITIES.filter(x=>x.enabled!==false)}
export const COUNT=ACTIVITIES.length;

